let state,clockId,pulseId;const $=s=>document.querySelector(s),board=$('#board'),nodeBy=id=>nodes.find(n=>n.id===id);
function reset(){clearInterval(clockId);clearInterval(pulseId);state={started:false,turn:0,lesions:4,jams:2,tool:'lesion',selected:null,disabled:new Set(),jammed:new Set(),contain:0,protected:100,collateralEvents:0,history:[],timeline:[],pendingAction:null,lastPaths:[],replaying:false,timeLeft:30,live:false};render();$('#startOverlay').classList.remove('hidden');$('#routeCards').classList.add('hidden');$('#replayBanner').classList.add('hidden');$('#advanceBtn').disabled=true;$('#quip').textContent='“The fly has no idea you’re here. Mostly because this is a graph.”';}
function el(tag,attrs={}){const e=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>e.setAttribute(k,v));return e}function pathData(a,b){const x1=a.x+24,x2=b.x-24,m=(x1+x2)/2;return `M${x1},${a.y} C${m},${a.y} ${m},${b.y} ${x2},${b.y}`}function edgeKey(a,b){return `${a}-${b}`}
function routeClass(a,b){if(state.disabled.has(a)||state.disabled.has(b))return 'edge dead';const active=new Set(state.lastPaths.flatMap(p=>p.edges.map(e=>edgeKey(...e))));if(active.has(edgeKey(a,b)))return state.turn>1?'edge reroute':'edge active';return 'edge'}
function render(){board.innerHTML='';edges.forEach(([a,b])=>board.append(el('path',{d:pathData(nodeBy(a),nodeBy(b)),class:routeClass(a,b),'data-edge':edgeKey(a,b)})));nodes.forEach(n=>{const g=el('g',{class:`node ${n.kind||''} ${state.disabled.has(n.id)?'disabled':''} ${state.jammed.has(n.id)?'jammed':''} ${state.selected===n.id?'selected':''}`,transform:`translate(${n.x} ${n.y})`,tabindex:n.locked?'-1':'0',role:'button','aria-label':n.name});g.append(el('circle',{r:n.kind?27:22}));if(n.kind==='source')g.append(el('circle',{r:34,class:'pulse-ring'}));const t=el('text',{'text-anchor':'middle',y:42});t.textContent=n.name;g.append(t);const m=el('text',{'text-anchor':'middle',y:56,class:'mini'});m.textContent=n.role;g.append(m);if(!n.locked){g.addEventListener('click',()=>selectNode(n.id));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' ')selectNode(n.id)})}board.append(g)});updateUI()}
function updateUI(){$('#turnTop').textContent=`${state.turn}/6`;$('#containTop').textContent=`${state.contain}%`;$('#timerTop').textContent=`00:${String(state.timeLeft??30).padStart(2,'0')}`;$('#lesionsLeft').textContent=state.lesions;$('#jamsLeft').textContent=state.jams;const damage=100-state.protected;$('#collateralValue').textContent=damage+'%';$('#collateralNote').textContent=damage?`${state.collateralEvents} damaging cut${state.collateralEvents===1?'':'s'} recorded`:'Protected routes intact';$('#collateralStatus').classList.toggle('damaged',damage>0);document.querySelectorAll('.tool').forEach(x=>x.classList.toggle('selected',x.dataset.tool===state.tool));}
function selectNode(id){if(!state.started)return;state.selected=id;const n=nodeBy(id);$('#emptyIntel').classList.add('hidden');$('#nodeIntel').classList.remove('hidden');$('#nodeRole').textContent=n.role;$('#nodeName').textContent=n.name;$('#nodeId').textContent=`MALECNS V1.0 // REAL TYPE GROUP`;$('#strengthBar').style.width=n.s+'%';$('#strengthVal').textContent=n.s;$('#loadBar').style.width=n.l+'%';$('#loadVal').textContent=n.l;$('#forecastText').textContent=n.f;const btn=$('#actionBtn'),used=state.disabled.has(id);btn.textContent=used?'ALREADY DISABLED':`${state.tool==='lesion'?'CUT':'JAM'} NODE`;btn.disabled=used||(state.tool==='lesion'?state.lesions<1:state.jams<1);render()}
function intervene(){const id=state.selected;if(!id)return;if(state.tool==='lesion'){const before=protectedScore();state.disabled.add(id);state.lesions--;const after=protectedScore(),loss=Math.max(0,before-after);state.protected=after;state.pendingAction={tool:'CUT',id,loss};if(loss>0){state.collateralEvents++;quip(`“Collateral alert: ${nodeBy(id).name} carried protected traffic.”`);toast(`⚠ COLLATERAL PENALTY: −${loss}% protected connectivity`)}else{quip(id==='gate'?'“Primary gate down. Protected routes remain intact.”':id==='ghost'?'“Ghost Gate cut. Quiet, precise, deeply satisfying.”':'“Clean cut. No protected connectivity lost.”');toast('Clean intervention. Protected routes intact.')}}else{state.jammed.add(id);state.jams--;state.pendingAction={tool:'JAM',id,loss:0};quip('“Temporary jam deployed. Neural hold music begins now.”');toast('Test jam armed. No permanent penalty.')}state.selected=null;$('#nodeIntel').classList.add('hidden');$('#emptyIntel').classList.remove('hidden');$('#advanceBtn').disabled=false;$('#systemState').textContent='INTERVENTION ARMED';render()}
function allPaths(target,blocked=new Set()){const adj={};edges.forEach(([a,b,w])=>(adj[a]??=[]).push({to:b,w}));const out=[];function walk(id,seen,ns,es,weights){if(id===target){out.push({nodes:ns,edges:es,capacity:Math.min(...weights)});return}for(const e of adj[id]||[]){if(blocked.has(e.to)||seen.has(e.to))continue;walk(e.to,new Set([...seen,e.to]),[...ns,e.to],[...es,[id,e.to]],[...weights,e.w])}}if(!blocked.has('LC4'))walk('LC4',new Set(['LC4']),['LC4'],[],[]);return out.sort((a,b)=>b.capacity-a.capacity)}
function targetPaths(){const blocked=new Set([...state.disabled,...state.jammed]),paths=allPaths('DNg108',blocked),chosen=[];for(const p of paths){const gate=p.nodes.at(-2);if(!chosen.some(c=>c.nodes.at(-2)===gate))chosen.push(p);if(chosen.length===6)break}return chosen}function totalCapacity(paths){return paths.reduce((s,p)=>s+p.capacity,0)}
function protectedScore(){const blocked=new Set(state.disabled),a=totalCapacity(allPaths('DNa13',blocked).slice(0,2)),b=totalCapacity(allPaths('DNa02',blocked).slice(0,2));return Math.round(100*Math.min(1,(a/1052+b/906)/2))}
function showRoutes(paths){const box=$('#routeCards');if(!paths.length){box.classList.add('hidden');return}box.innerHTML=paths.map((p,i)=>`<article class="route-card" data-route="${i}"><b>${p.capacity}</b><small>ROUTE ${String.fromCharCode(65+i)}</small><strong>${p.nodes.at(-2)} GATE</strong><p>${p.nodes.map(id=>nodeBy(id).name).join(' → ')}</p></article>`).join('');box.classList.remove('hidden');box.querySelectorAll('.route-card').forEach(card=>{card.onmouseenter=()=>highlightRoute(paths[+card.dataset.route]);card.onmouseleave=()=>render()})}
function highlightRoute(path){const keep=new Set(path.edges.map(e=>edgeKey(...e)));board.querySelectorAll('.edge').forEach(e=>{e.style.opacity=keep.has(e.dataset.edge)?'1':'.12';e.style.strokeWidth=keep.has(e.dataset.edge)?'5':'1'})}
function advance(){if(state.turn>=6)return;state.turn++;const paths=targetPaths(),activeJams=[...state.jammed];state.lastPaths=paths;state.history.push(paths);state.contain=Math.round(100*Math.max(0,1-totalCapacity(paths)/2534));state.protected=protectedScore();state.timeline.push({turn:state.turn,action:state.pendingAction||{tool:'OBSERVE',id:null,loss:0},disabled:[...state.disabled],jammed:activeJams,paths,contain:state.contain,protected:state.protected});state.pendingAction=null;state.jammed.clear();$('#advanceBtn').disabled=true;$('#systemState').textContent=paths.length>1?`${paths.length} ROUTES ACTIVE`:paths.length?'ONE ROUTE ACTIVE':'SIGNAL CONTAINED';render();showRoutes(paths);animatePaths(paths);if(!paths.length)quip('“Full containment. The target has been stood up by every signal.”');else if(paths.length===6)quip('“Six measured MaleCNS routes are active. The fly has options.”');else if(state.turn>1)quip(`“It rerouted through ${paths.map(p=>nodeBy(p.nodes.at(-2)).name).join(' and ')}. Rude.”`);else quip('“Contact. Multiple paths are carrying signal. Try looking tactical.”');if(state.turn===6||(!paths.length&&state.turn>=2))setTimeout(finish,1200)}
function animatePaths(paths){const colors=['var(--cyan)','var(--amber)','var(--violet)','var(--acid)','#ff7ad9','#7aff8e'];paths.forEach((path,p)=>path.edges.forEach(([a,b],i)=>setTimeout(()=>{const B=nodeBy(b),c=el('text',{x:B.x,y:B.y+7,class:'courier','text-anchor':'middle',style:`filter:drop-shadow(0 0 8px ${colors[p]})`});c.textContent='🪰';board.append(c);setTimeout(()=>c.remove(),720)},i*260+p*110)))}
function finish(){stopLive();const containment=state.contain,precision=state.protected,unused=state.lesions+state.jams,damage=100-precision,score=Math.max(0,Math.min(100,Math.round(containment-damage*.9+unused*2)));let rank='C',title='TARGET PARTIALLY CONTAINED',copy='The intervention needs another pass.';if(containment>=95&&precision>=95){rank='S';title='SURGICAL SABOTEUR';copy='Full containment with protected structural pathways intact.'}else if(containment>=80&&precision>=85&&score>=75){rank='A';title='CLEAN GETAWAY';copy='Strong containment with limited collateral disruption.'}else if(containment>=60&&precision>=60){rank='B';title='MESSY, BUT EFFECTIVE';copy='The target was suppressed, but protected connectivity paid a price.'}else if(precision<60){rank='D';title='COLLATERAL CATASTROPHE';copy='Target suppression cannot compensate for destroying unrelated pathways.'}$('#rank').textContent=rank;$('#resultTitle').textContent=title;$('#resultCopy').textContent=copy;$('#finalContain').textContent=containment+'%';$('#finalPrecision').textContent=precision+'%';$('#finalStyle').textContent=damage?`−${Math.round(damage*.9)}`:'+'+(unused*2);$('#youScore').textContent=score;$('#youBar').style.setProperty('--w',score+'%');const broad=['PVLP137','PVLP141','LC31b','LAL028','LT51'].some(id=>state.disabled.has(id));$('#insight').innerHTML=broad?`<strong>Collateral penalty:</strong> ${damage}% of protected structural connectivity was lost. Shared hubs are powerful but imprecise targets.`:'<strong>What happened:</strong> You targeted route-specific gates rather than the biggest hubs—the structural equivalent of stealing the keys instead of demolishing the building.';$('#resultDialog').showModal()}
function stopLive(){clearInterval(clockId);clearInterval(pulseId);clockId=null;pulseId=null;if(state)state.live=false}
function startLive(){state.live=true;clockId=setInterval(()=>{state.timeLeft=Math.max(0,state.timeLeft-1);updateUI();if(state.timeLeft===0){stopLive();finish()}},1000);setTimeout(()=>{if(state.live&&state.turn===0)advance()},1200);pulseId=setInterval(()=>{if(state.live&&state.turn<6)advance()},4200)}
