function playDetailedReplay(){if(!state.timeline.length)return;$('#resultDialog').close();const finished=state,steps=finished.timeline;state={...finished,started:false,replaying:true,disabled:new Set(),jammed:new Set(),lastPaths:[],contain:0,protected:100};const banner=$('#replayBanner');banner.classList.remove('hidden');$('#routeCards').classList.add('hidden');$('#replayTitle').textContent='INTACT NETWORK';$('#replayDetail').textContent='Baseline: all structural routes are available.';$('#replayProgress').style.width='5%';render();let i=0;const next=()=>{if(i>=steps.length){$('#replayTitle').textContent='PLAYBACK COMPLETE';$('#replayDetail').textContent=`Final containment ${finished.contain}% · protected connectivity ${finished.protected}%`;$('#replayProgress').style.width='100%';setTimeout(()=>{state=finished;banner.classList.add('hidden');render();showRoutes(state.lastPaths);$('#resultDialog').showModal()},2200);return}const s=steps[i++],a=s.action;state.turn=s.turn;state.disabled=new Set(s.disabled);state.jammed=new Set(s.jammed);state.lastPaths=s.paths;state.contain=s.contain;state.protected=s.protected;render();showRoutes(s.paths);animatePaths(s.paths);const label=a.tool==='OBSERVE'?'BASELINE PROPAGATION':`${a.tool}: ${nodeBy(a.id).name}`;$('#replayTitle').textContent=`STEP ${i} — ${label}`;$('#replayDetail').textContent=a.loss?`Protected connectivity −${a.loss}%. ${s.paths.length} target route${s.paths.length===1?'':'s'} remain.`:`No collateral loss. ${s.paths.length} target route${s.paths.length===1?'':'s'} remain.`;$('#replayProgress').style.width=`${Math.round(i/steps.length*100)}%`;setTimeout(next,2400)};setTimeout(next,1100)}
